using Astronomy.MediaFactory.Core.DocumentaryBlueprint;
namespace Astronomy.MediaFactory.Tests.DocumentaryBlueprint; public sealed class DocumentaryMediaProjectionKnowledgeExtractionTests { [Theory][InlineData("orion")][InlineData("leo")][InlineData("conjunction")] public void Extraction_is_explicit_topic_filtered_and_pointer_exact(string name){var r=name=="orion"?DocumentaryMediaProjectionFixture.Orion():name=="leo"?DocumentaryMediaProjectionFixture.Leo():DocumentaryMediaProjectionFixture.Conjunction();var facts=DocumentaryMediaKnowledgeExtractor.Extract(r);Assert.NotEmpty(facts);Assert.All(facts.SelectMany(x=>x.KnowledgeReferences),x=>Assert.StartsWith("/semanticFacts/",x.JsonPointer));var p=DocumentaryMediaProjectionFixture.Complete(r);Assert.DoesNotContain(p.Variants.SelectMany(x=>x.Scenes).Select(x=>x.Title),x=>name=="orion"&&x.Contains("Leo",StringComparison.Ordinal));} }
